int main(int argc, char *argv[]) {
    // sum the number of sales for the first quarter
	int sales = 0;
	for (int i = 1; i <= 3; i++) {
		sales += getMonthlySales(i);
	}

	printf("Total sales for the first quarter: %d\n", sales);

    // sum the number of sales for the second quarter
	sales = 0;
	for (int i = 4; i <= 6; i++) {
		sales += getMonthlySales(i);
	}

	printf("Total sales for the second quarter: %d\n", sales);

    // sum the number of sales for the third quarter
	sales = 0;
	for (int i = 7; i <= 9; i++) {
		sales += getMonthlySales(i);
	}

	printf("Total sales for the third quarter: %d\n", sales);

    // sum the number of sales for the fourth quarter
	sales = 0;
	for (int i = 10; i <= 12; i++) {
		sales += getMonthlySales(i);
	}

	printf("Total sales for the fourth quarter: %d\n", sales);

    return 0;
}
