```c
#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    // malloc a large buffer and copy in 100 characters from stdin
    char* buf = malloc(1024);
	int i = 0;
    while (i < 1024) {
        buf[i] = getchar();
        i++;
    }

    // print out the buffer in reverse order
    for (int j = i - 1; j >= 0; j--) {
        printf("%c", buf[j]);
    }
    printf("\n");

    // free the buffer
    free(buf);

    return 0;
}
