        printf("Error opening file!\n");
        return 1;
    }

    // read data from file
    float a;
    float b;
    float c;
    fscanf(fp, "%f,%f,%f", &a, &b, &c);

    // print data
    printf("a = %.2f\n", a);
    printf("b = %.2f\n", b);
    printf("c = %.2f\n", c);

    // close file
    fclose(fp);

    return 0;
}
