#include <sys/types.h>
#include <sys/stat.h>
#include <dirent.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>

int main(int argc, char *argv[]) {
    // get a directory name from the command line
    char *dirname = argv[1];

    // open the directory for reading
    int dirfd = open(dirname, O_RDONLY);
    if (dirfd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // read the directory entries
    struct dirent *entry;
    while ((entry = readdir(dirfd))!= NULL) {
        // skip "." and ".." entries
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        // get the full path of the entry
        char path[256] = {0};
        sprintf(path, "%s/%s", dirname, entry->d_name);

        // get the entry's file status
        struct stat statbuf = {0};
        if (stat(path, &statbuf) < 0) {
            perror("stat");
            exit(EXIT_FAILURE);
        }

        // print the entry's name and type
        if (S_ISDIR(statbuf.st_mode)) {
            printf("d %s\n", entry->d_name);
        } else if (S_ISREG(statbuf.st_mode)) {
            printf("- %s\n", entry->d_name);
        } else if (S_ISLNK(statbuf.st_mode)) {
            printf("l %s\n", entry->d_name);
        } else if (S_ISCHR(statbuf.st_mode)) {
            printf("c %s\n", entry->d_name);
        } else if (S_ISBLK(statbuf.st_mode)) {
            printf("b %s\n", entry->d_name);
        } else if (S_ISFIFO(statbuf.st_mode)) {
            printf("p %s\n", entry->d_name);
        } else if (S_ISSOCK(statbuf.st_mode)) {
            printf("s %s\n", entry->d_name);
        }
    }

    // close the directory
    close(dirfd);

    return 0;
}
```

