#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>

int main(int argc, char *argv[]) {
    // get a directory name from the command line
    char *dirname = argv[1];

    // change the directory's owner to the current user
    int ret = chown(dirname, getuid(), getgid());
    if (ret < 0) {
        perror("chown");
        exit(EXIT_FAILURE);
    }

    // change the directory's mode to 0755
    ret = chmod(dirname, 0755);
    if (ret < 0) {
