    // given an index in argv[1], return the corresponding argument from argv[]
    if (argc < 2) {
        printf("Usage: %s <index>\n", argv[0]);
        exit(1);
    }

    int index = atoi(argv[1]);
    if (index < 0 || index >= argc) {
        printf("Invalid index: %d\n", index);
